package com.mohymods.kingdomsmp.profession;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
class RepairEvidenceTest {
 @Test void fourNativeIdentitiesCountOnceAndSurviveExactSaveReload(){var e=new RepairEvidence();var owner=UUID.randomUUID();for(int i=0;i<4;i++){var id=e.worn(null,owner,"minecraft:iron_pickaxe",12);assertTrue(e.repair(id,owner,ProfessionRank.APPRENTICE,"minecraft:iron_pickaxe",12,0,1,2));assertFalse(e.repair(id,owner,ProfessionRank.APPRENTICE,"minecraft:iron_pickaxe",12,0,1,2));assertEquals(id,e.worn(id,owner,"minecraft:iron_pickaxe",12));assertFalse(e.repair(id,owner,ProfessionRank.APPRENTICE,"minecraft:iron_pickaxe",12,0,1,2));}var restored=RepairEvidence.load(e.save());assertEquals(e.save(),restored.save());assertEquals(4,restored.count(owner,ProfessionRank.APPRENTICE));assertEquals(0,restored.count(owner,ProfessionRank.JOURNEYMAN));assertEquals(0,restored.count(UUID.randomUUID(),ProfessionRank.APPRENTICE));}
 @Test void unknownWrongItemStaleWearNoMaterialOrXpAndNonImprovingRepairsFailClosed(){var e=new RepairEvidence();var p=UUID.randomUUID();var id=e.worn(null,p,"minecraft:iron_axe",20);assertFalse(e.repair(UUID.randomUUID(),p,ProfessionRank.APPRENTICE,"minecraft:iron_axe",20,0,1,1));assertFalse(e.repair(id,p,ProfessionRank.APPRENTICE,"minecraft:iron_sword",20,0,1,1));for(int[] n:new int[][]{{19,0,1,1},{20,20,1,1},{20,-1,1,1},{20,0,0,1},{20,0,1,0}})assertFalse(e.repair(id,p,ProfessionRank.APPRENTICE,"minecraft:iron_axe",n[0],n[1],n[2],n[3]));assertEquals(0,e.count(p,ProfessionRank.APPRENTICE));assertNull(e.worn(null,p,"minecraft:diamond_pickaxe",10));}
 @Test void malformedSavedProofsNeverResetIntoFreshAwardableState(){var e=new RepairEvidence();e.worn(null,UUID.randomUUID(),"minecraft:iron_axe",10);var tag=e.save();tag.getList("items",Tag.TAG_COMPOUND).getCompound(0).putInt("damage",-1);assertThrows(IllegalArgumentException.class,()->RepairEvidence.load(tag));var wrong=e.save();wrong.putInt("schema",2);assertThrows(IllegalArgumentException.class,()->RepairEvidence.load(wrong));var duplicate=e.save();var list=duplicate.getList("items",Tag.TAG_COMPOUND);list.add(list.getCompound(0).copy());assertThrows(IllegalArgumentException.class,()->RepairEvidence.load(duplicate));}
}
